export { anatomy, type MeterPart, parts } from "./meter.anatomy";
export { connect } from "./meter.connect";
export { getLabelId, getRootId, getValueTextId } from "./meter.dom";
export { machine } from "./meter.machine";
export type {
  MeterApi,
  MeterMachineProps,
  MeterSchema,
  MeterValence,
  MeterValueChangeDetails,
  ResolvedMeterMachineProps,
} from "./meter.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type MeterPart = "root" | "label" | "track" | "range" | "valueText";

export const anatomy: Anatomy<MeterPart> = createAnatomy("meter").parts(
  "root",
  "label",
  "track",
  "range",
  "valueText",
);

export const parts: Record<MeterPart, AnatomyPart> = anatomy.build();

export interface MeterCssVars {
  // --- written ---
  /** Where the value sits between the minimum and the maximum. */
  "--sui-meter-percent": "<percentage>";
}

import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { parts } from "./meter.anatomy";
import { getLabelId, getRootId, getValueTextId } from "./meter.dom";
import type { MeterApi, MeterSchema } from "./meter.types";

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export function connect<T extends PropTypes>(
  service: Service<MeterSchema>,
  normalize: NormalizeProps<T>,
): MeterApi<T> {
  const { context, prop, computed, send, scope } = service;

  const value = context.get("value");
  const percent = computed("percent");
  const valence = computed("valence");
  const valueAsText = computed("valueAsText");

  /**
   * The one channel the valence has to assistive technology. `data-valence` is
   * a styling hook, the colour ramps are 1.01:1 apart in greyscale, and the
   * visible value text is `aria-hidden` because the root already announces the
   * number — so without this the grading reaches nobody who cannot see it.
   *
   * Appended rather than substituted, and only for a region the consumer named:
   * the number is what the meter is for, and a core that has not been given the
   * words does not invent them.
   */
  const valenceLabel = valence === "none" ? undefined : prop("valenceLabels")?.[valence];
  const valueAsAnnouncedText =
    valenceLabel === undefined ? valueAsText : `${valueAsText}, ${valenceLabel}`;

  const stateAttrs = {
    "data-orientation": prop("orientation"),
    // Absent while the gauge is neutral, never present-and-empty — the same
    // rule as `data-scroll`.
    "data-valence": valence === "none" ? undefined : valence,
  };

  return {
    value,
    percent,
    valence,
    valueAsText,
    valueAsAnnouncedText,

    setValue(next: number): void {
      send({ type: "VALUE.SET", value: next });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        role: "meter",
        dir: prop("dir"),
        // Only when the label part is really there: a dangling IDREF would
        // leave the gauge with no accessible name at all and stop a consumer's
        // own `aria-label` from winning — the same guard as `progress`, and the
        // same answer a server gives before the mount effect.
        "aria-labelledby": context.get("hasLabel") ? getLabelId(scope) : undefined,
        // Always present — a meter has no indeterminate state to drop them for.
        "aria-valuemin": prop("min"),
        "aria-valuemax": prop("max"),
        "aria-valuenow": clamp(value, prop("min"), prop("max")),
        "aria-valuetext": valueAsAnnouncedText,
        style: { "--sui-meter-percent": `${percent}%` },
      }),

    getLabelProps: (): T["element"] =>
      normalize.element({ ...parts.label.attrs, ...stateAttrs, id: getLabelId(scope) }),

    getTrackProps: (): T["element"] => normalize.element({ ...parts.track.attrs, ...stateAttrs }),

    getRangeProps: (): T["element"] => normalize.element({ ...parts.range.attrs, ...stateAttrs }),

    getValueTextProps: (): T["element"] =>
      normalize.element({
        ...parts.valueText.attrs,
        ...stateAttrs,
        id: getValueTextId(scope),
        // The root already publishes the value to assistive technology through
        // `aria-valuetext`; reading the same number twice helps nobody.
        "aria-hidden": "true",
      }),
  };
}

import { query } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "meter";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getValueTextId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "valueText");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/**
 * `aria-labelledby` may only point at an id that exists. A gauge rendered
 * without the optional label part — the commonest way one ships — would
 * otherwise have no accessible name at all, and axe is right to call that a
 * violation.
 */
export function hasLabel(scope: Scope): boolean {
  return query(getRootEl(scope), '[data-part~="meter:label"]') !== null;
}

/**
 * One state, the same shape as `progress` and for the same reason: nothing to
 * interact with, but a value that can be controlled or not, a range to clamp
 * against, ids to derive and a label part to detect — which is exactly what a
 * service provides and a bare prop getter would have to reinvent.
 *
 * Where the two split is what the value *means*. A progress value can be
 * unknown; a meter's cannot — a gauge always reads something, so `value` is a
 * number and there is no indeterminate branch anywhere. What a meter has
 * instead is quality: `low`/`high`/`optimum` grade the value the way the HTML
 * `<meter>` element does, by the distance between regions.
 */

import { observeChildren } from "../../dom/observers";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getRootEl, hasLabel } from "./meter.dom";
import type { MeterSchema, MeterValence } from "./meter.types";

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export const machine: Machine<MeterSchema> = createMachine<MeterSchema>({
  props({ props }) {
    return {
      min: 0,
      max: 100,
      orientation: "horizontal",
      locale: "en-US",
      formatOptions: { style: "percent" },
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<number>(() => ({
        // Coalesced on absence, not nullishness, and onto `min` rather than 0:
        // a gauge over [2, 8] starts at 2.
        defaultValue: prop("defaultValue") === undefined ? prop("min") : prop("defaultValue"),
        value: prop("value"),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "meter value",
      })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  computed: {
    percent({ context, prop }) {
      const min = prop("min");
      const max = prop("max");
      if (max <= min) return 100;
      return ((clamp(context.get("value"), min, max) - min) / (max - min)) * 100;
    },

    valence({ context, prop }): MeterValence {
      const low = prop("low");
      const high = prop("high");
      if (low === undefined && high === undefined) return "none";
      const min = prop("min");
      const max = prop("max");
      const lo = clamp(low ?? min, min, max);
      // Floored at `lo`, so a crossed pair normalises instead of turning the
      // middle region inside out.
      const hi = clamp(high ?? max, lo, max);
      const opt = clamp(prop("optimum") ?? (min + max) / 2, min, max);
      // Bounds belong to the middle region, the way `<meter>` reads them: a
      // value sitting exactly on `low` or `high` is not outside yet.
      const region = (x: number): number => (x < lo ? 0 : x > hi ? 2 : 1);
      const distance = Math.abs(region(clamp(context.get("value"), min, max)) - region(opt));
      return distance === 0 ? "optimum" : distance === 1 ? "suboptimal" : "critical";
    },

    valueAsText({ computed, context, prop }) {
      const options = prop("formatOptions");
      // A percentage is the *level*, expressed as the fraction Intl expects.
      // Anything else formats the value itself: "620 GB" is the number 620, not
      // the share of the disk it happens to occupy.
      const isPercent = options.style === "percent";
      const value = clamp(context.get("value"), prop("min"), prop("max"));
      return new Intl.NumberFormat(prop("locale"), options).format(
        isPercent ? computed("percent") / 100 : value,
      );
    },
  },

  initialState() {
    return "idle";
  },

  effects: ["trackParts"],

  watch({ scope, track, action }) {
    track(
      () => [hasLabel(scope)],
      () => action(["syncParts"]),
    );
  },

  on: {
    "VALUE.SET": { actions: ["setValue"] },
    "PARTS.SYNC": { actions: ["syncParts"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    actions: {
      setValue({ context, event, prop }) {
        if (event.type !== "VALUE.SET") return;
        context.set("value", clamp(event.value, prop("min"), prop("max")));
      },
      syncParts({ context, scope }) {
        context.set("hasLabel", hasLabel(scope));
      },
    },

    effects: {
      trackParts({ scope, send }) {
        send({ type: "PARTS.SYNC" });
        return observeChildren(getRootEl(scope), () => send({ type: "PARTS.SYNC" }));
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, Orientation } from "../../types";

export interface MeterValueChangeDetails {
  readonly value: number;
}

/**
 * How the value sits against `low`/`high`/`optimum`, the way the HTML `<meter>`
 * element grades it: the distance between the value's region and the optimum's.
 * `"none"` while neither threshold is given — a neutral gauge has no opinion.
 */
export type MeterValence = "none" | "optimum" | "suboptimal" | "critical";

/**
 * What each graded region is *called*, so the valence reaches assistive
 * technology at all.
 *
 * Without this the grading is carried by colour and by nothing else — the
 * success and warning ramps are 1.01:1 apart in greyscale, `data-valence` is a
 * styling hook no screen reader reads, and the visible value text is
 * `aria-hidden` because the root already announces the number. A gauge that says
 * "18 %" in a calm voice while it is painted red is a gauge that lied.
 *
 * The strings stay the consumer's: a headless core has no business inventing
 * "Low" or "Critical", and it certainly has no business inventing them in
 * English. Whatever is given is appended to `aria-valuetext`; whatever is left
 * out simply is not announced, which is today's behaviour for that region.
 */
export type MeterValenceLabels = Partial<Record<Exclude<MeterValence, "none">, string>>;

/**
 * `role="meter"` requires an accessible name: render the label part or pass
 * `aria-label` on the root — a bare meter is an axe violation.
 */
export interface MeterMachineProps {
  readonly dir?: Direction | undefined;
  /** Controlled. Never null: a meter always has a value. */
  readonly value?: number | undefined;
  /** Uncontrolled. Defaults to `min`, not 0 — a range [2, 8] starts at 2. */
  readonly defaultValue?: number | undefined;
  readonly min?: number | undefined;
  readonly max?: number | undefined;
  /** Low bound of the middle region. Absent along with `high` → no valence. */
  readonly low?: number | undefined;
  readonly high?: number | undefined;
  /** The ideal point. Effective default: `(min + max) / 2`, like `<meter>`. */
  readonly optimum?: number | undefined;
  readonly orientation?: Orientation | undefined;
  readonly locale?: string | undefined;
  /** Passed to `Intl.NumberFormat` for the value text. Percent by default. */
  readonly formatOptions?: Intl.NumberFormatOptions | undefined;
  /** The only channel the valence has to assistive technology — see the type. */
  readonly valenceLabels?: MeterValenceLabels | undefined;
  readonly onValueChange?: ((details: MeterValueChangeDetails) => void) | undefined;
}

/**
 * `low`/`high`/`optimum` stay optional once resolved: their *absence* carries
 * meaning — no thresholds, no valence.
 */
export interface ResolvedMeterMachineProps extends MeterMachineProps {
  readonly min: number;
  readonly max: number;
  readonly orientation: Orientation;
  readonly locale: string;
  readonly formatOptions: Intl.NumberFormatOptions;
}

export interface MeterSchema extends MachineSchema {
  state: "idle";
  props: ResolvedMeterMachineProps;
  context: { value: number; hasLabel: boolean };
  computed: { percent: number; valence: MeterValence; valueAsText: string };
  event: { type: "VALUE.SET"; value: number } | { type: "PARTS.SYNC" };
  action: "setValue" | "syncParts";
  effect: "trackParts";
}

export interface MeterApi<T extends PropTypes = PropTypes> {
  readonly value: number;
  /** Never null — a meter has no indeterminate state. */
  readonly percent: number;
  /** For rendering the valence as text on the consumer's side. */
  readonly valence: MeterValence;
  readonly valueAsText: string;
  /**
   * What the root announces: `valueAsText`, plus the valence label when the
   * consumer named this region. The visible text stays `valueAsText` — the
   * grading belongs in the announcement, not painted twice on screen.
   */
  readonly valueAsAnnouncedText: string;
  setValue(value: number): void;
  getRootProps(): T["element"];
  getLabelProps(): T["element"];
  getTrackProps(): T["element"];
  getRangeProps(): T["element"];
  getValueTextProps(): T["element"];
}

export type {
  MeterMachineProps,
  MeterValence,
  MeterValueChangeDetails,
} from "@standarui/core/meter";
export { Meter, type MeterComposedProps, type MeterParts } from "./composed";
export {
  type MeterApi,
  MeterLabel,
  MeterRange,
  MeterRoot,
  type MeterRootProps,
  MeterTrack,
  MeterValueText,
  type UseMeterProps,
  useMeter,
} from "./meter";

import * as meter from "@standarui/core/meter";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type MeterApi = meter.MeterApi<ReactPropTypes>;

const MeterContext = createPartContext<MeterApi>("Meter");

export interface UseMeterProps extends meter.MeterMachineProps, MachineRuntimeProps {}

export function useMeter(props: UseMeterProps): MeterApi {
  return meter.connect(useMachine(meter.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "value",
  "defaultValue",
  "min",
  "max",
  "low",
  "high",
  "optimum",
  "orientation",
  "locale",
  "formatOptions",
  "valenceLabels",
  "onValueChange",
] as const;

export interface MeterRootProps extends UseMeterProps, PartProps<"div", UseMeterProps> {}

export function MeterRoot(props: MeterRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useMeter(machineProps);

  return (
    <MeterContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </MeterContext.Provider>
  );
}

export const MeterLabel: (props: PartProps<"span">) => ReactNode = createPart(MeterContext, {
  name: "MeterLabel",
  element: "span",
  props: (api) => api.getLabelProps(),
});

export const MeterTrack: (props: PartProps<"div">) => ReactNode = createPart(MeterContext, {
  name: "MeterTrack",
  element: "div",
  props: (api) => api.getTrackProps(),
});

export const MeterRange: (props: PartProps<"div">) => ReactNode = createPart(MeterContext, {
  name: "MeterRange",
  element: "div",
  props: (api) => api.getRangeProps(),
});

export const MeterValueText: (props: PartProps<"span">) => ReactNode = createPart(MeterContext, {
  name: "MeterValueText",
  element: "span",
  props: (api) => api.getValueTextProps(),
});
